// Source: st04.ecl.txt:1632-1682 (MainSub05) and 335-813 (GirlA01..A04 deps).
// Source S=0 is MainSub05 entry; this card places it after OPENING_BUFFER.

const TIME_LIMIT: int = 2400;
const OPENING_BUFFER: int = 120;

// Spawn schedule (MainSub05): each round
//   9 x GirlA01 x=-192+48i (right sweep), 7 x GirlA03 x=192-64i, 3f apart, then wait(100)
//   9 x GirlA02M x=-192+48i (mirrored, left sweep), 7 x GirlA04 x=192-64i, 3f apart, wait(100)
// Round length 496 frames; 3 rounds -> 1488. main() clears the field 300 frames later.

// ---------------------------------------------------------------- volley helpers

// Source etCount/etSpeed: layer speed v(q) = s0 + (s1-s0)*q/(M-1); M=1 uses s0 only.
// Every source emitter here carries etEx(type 2, a=1) ANIM; its birth retreat
// (position -= 4*velocity) is kept per the approved policy.
sub fire_line(x: fx, y: fx, a: angle, layers: int, s0: fx, s1: fx, shape: int, color: int) {
    for q in 0..layers {
        var speed: fx = s0;
        if layers > 1 {
            speed = s0 + (s1 - s0) * (q as fx) / ((layers - 1) as fx);
        }
        var sx: fx = x - 4.0fx * speed * cos(a);
        var sy: fx = y - 4.0fx * speed * sin(a);
        _ = fire(shape, color, sx, sy, speed, a, none, none);
    }
}

// GirlA04 0x200000 VELTIME(a=60, r=0.8/0.9/1.0, s<=-999990 keeps the birth angle):
// scalar speed ramps to r along the fixed birth direction.
xformdef VELTIME_TO(target: fx) {
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// Source etAim mode 3 fixed ring: angle = base + (i*65536)/n + q*delta; delta=0 here.
sub fire_ring_vt(x: fx, y: fx, base: angle, n: int, layers: int, s0: fx, s1: fx, vt: fx)
{
    for q in 0..layers {
        var speed: fx = s0;
        if layers > 1 {
            speed = s0 + (s1 - s0) * (q as fx) / ((layers - 1) as fx);
        }
        for i in 0..n {
            var a: angle = base + (((i * 65536) / n) as angle);
            var sx: fx = x - 4.0fx * speed * cos(a);
            var sy: fx = y - 4.0fx * speed * sin(a);
            _ = fire(TH16_RICE, 2, sx, sy, speed, a, VELTIME_TO(vt), none);
        }
    }
}

// ---------------------------------------------------------------- attack subs
// Source time labels are kept as cumulative waits (age measured from enemy spawn).

// GirlA01_at (369-412): slot0, etAim 1 (fixed fan), type 8 color 6, 90 deg,
// 5 shots 5f apart then wait(30), 40 cycles. First shot at age 60.
async sub girl_a01_at() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1.5fx;                       // E 1.5 / N 2.0 / H,L 3.5
    if rank >= 1 { s0 = 2.0fx; }
    if rank >= 2 { layers = 2; s0 = 3.5fx; }
    wait(60);
    for k in 0..40 {
        for j in 0..5 {
            fire_line($self_x, $self_y, 90deg, layers, s0, 2.2fx, TH16_RICE, 6);
            wait(5);
        }
        wait(30);
    }
}

// GirlA01_at2 (414-451): slot1, etAim 0 (aimed fan), type 8 color 2, one shot per
// 60f for 40 cycles. N:1 layer 2.2, H:1 layer 3.0, L:2 layers 3.5/2.2.
async sub girl_a01_at2() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 2.2fx;
    if rank >= 2 { s0 = 3.0fx; }
    if rank >= 3 { layers = 2; s0 = 3.5fx; }
    wait(160);
    for k in 0..40 {
        var a: angle = atan2($player_y - $self_y, $player_x - $self_x);
        fire_line($self_x, $self_y, a, layers, s0, 2.2fx, TH16_RICE, 2);
        wait(60);
    }
}

