// GirlA03_at (615-668): slot0, etAim 0 (aimed fan), type 8 color 6,
// 3 cycles; each sets a fresh +-10 deg center offset, bursts diffI(B)=1/3/3/3
// shots 3f apart, then waits 140/70/35/35.
async sub girl_a03_at() {
    var rank: int = global(GVAR_RANK);
    var layers: int = 1;
    var s0: fx = 1.5fx;                       // E 1.5 / N 2.8 / H,L 3.5
    var burst: int = 1;                       // E 1 / N,H,L 3
    var pause: int = 140;                     // E 140 / N 70 / H,L 35
    if rank == 1 { s0 = 2.8fx; burst = 3; pause = 70; }
    if rank == 2 { s0 = 3.5fx; burst = 3; pause = 35; }
    if rank == 3 { layers = 2; s0 = 3.5fx; burst = 3; pause = 35; }
    wait(60);
    for k in 0..3 {
        var r: int = rand(65536);
        var u: fx = (r - 32768) as fx / 32768;   // signed unit, RANDF2 range
        var off: int = (1820fx * u) as int;      // +-10 deg in BAM
        for j in 0..burst {
            var a: angle = atan2($player_y - $self_y, $player_x - $self_x)
                + (off as angle);
            fire_line($self_x, $self_y, a, layers, s0, 2.2fx, TH16_RICE, 6);
            wait(3);
        }
        wait(pause);
    }
}

// GirlA04_at (742-813): slot0, etAim 3 (fixed ring), type 8 color 2,
// ring base 90+-10 deg each cycle, 30 cycles; one volley then wait(3)+150/50/50/40.
// Layers: E 1, N/H/L 2. VELTIME target speed 0.8/0.8/0.9/1.0.
async sub girl_a04_at() {
    var rank: int = global(GVAR_RANK);
    var n: int = 3;                           // E 3 / N,H,L 8
    var layers: int = 1;
    var s0: fx = 1.5fx;                       // E 1.5 / N 3.5 / H,L 3.8
    var vt: fx = 0.8fx;
    var pause: int = 150;                     // E 150 / N,H 50 / L 40
    if rank == 1 { n = 8; layers = 2; s0 = 3.5fx; pause = 50; }
    if rank == 2 { n = 8; layers = 2; s0 = 3.8fx; vt = 0.9fx; pause = 50; }
    if rank == 3 { n = 8; layers = 2; s0 = 3.8fx; vt = 1.0fx; pause = 40; }
    wait(60);
    for k in 0..30 {
        var r: int = rand(65536);
        var u: fx = (r - 32768) as fx / 32768;
        var off: int = (1820fx * u) as int;
        var base: angle = 90deg + (off as angle);
        fire_ring_vt($self_x, $self_y, base, n, layers, s0, 2.2fx, vt);
        wait(3);
        wait(pause);
    }
}

