// ---------------------------------------------------------------- wave + shell

async sub wave() {
    wait(OPENING_BUFFER);
    for round in 0..3 {
        for i1 in 0..9 {
            _ = spawn_enemy((-192 + i1 * 48) as fx, 32fx, 200, 0, 1000, 0, girl_a01_main);
            wait(3);
        }
        wait(100);
        for i2 in 0..7 {
            _ = spawn_enemy((192 - i2 * 64) as fx, 32fx, 200, 0, 1000, 0, girl_a03_main);
            wait(3);
        }
        wait(100);
        for i3 in 0..9 {
            _ = spawn_enemy((-192 + i3 * 48) as fx, 32fx, 200, 0, 1000, 0, girl_a02_main);
            wait(3);
        }
        wait(100);
        for i4 in 0..7 {
            _ = spawn_enemy((192 - i4 * 64) as fx, 32fx, 200, 0, 1000, 0, girl_a04_main);
            wait(3);
        }
        wait(100);
    }
    wait(300);                                 // main(): wait(300) then enmKillAll
    kill_all_enemies(KILL_SILENT);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

